import itertools

#: Gower distance with equal weights (income min-max, profession & mother tongue nominal, native place ordinal)
people = {"Ram": (70000, "Doctor", "Bengali", 1), "Balram": (50000, "Data Scientist", "Hindi", 2),
          "Bharat": (60000, "Carpenter", "Hindi", 3), "Kishan": (80000, "Doctor", "Bhojpuri", 4)}
inc = [p[0] for p in people.values()]; lo, hi = min(inc), max(inc)
def gower(a, b):
    A, B = people[a], people[b]
    parts = [abs(A[0] - B[0]) / (hi - lo), float(A[1] != B[1]), float(A[2] != B[2]), abs(A[3] - B[3]) / 3]
    return sum(parts) / 4, sum(parts)
for a, b in itertools.combinations(people, 2):
    g, s = gower(a, b); print(f"d({a},{b}) sum={s:.2f}  gower={g:.3f}")
